<script setup lang="ts">import {computed,ref} from "vue";import {useRouter} from "vue-router";import {Plus} from "lucide-vue-next";import AppShell from "@/components/zs/AppShell.vue";import PageHeader from "@/components/zs/PageHeader.vue";import Panel from "@/components/zs/Panel.vue";import StatCard from "@/components/zs/StatCard.vue";import DataTable,{type Column} from "@/components/zs/DataTable.vue";import Toolbar from "@/components/zs/Toolbar.vue";import SearchInput from "@/components/zs/SearchInput.vue";import StatusBadge from "@/components/zs/StatusBadge.vue";import SidePanel from "@/components/zs/SidePanel.vue";import Field from "@/components/zs/Field.vue";import ZButton from "@/components/zs/ZButton.vue";import {useAsyncData} from "@/composables/useAsyncData";import {operationsRepository} from "@/services/operations/repository";import {useCompanyStore} from "@/stores/company";import {formatMoney} from "@/lib/money";import {showToast} from "@/composables/useToast";import {setPageMeta} from "@/lib/page-meta";import type {PurchaseOrder} from "@/types/operations";setPageMeta("Purchase Orders","Purchase approval, receiving and bill-conversion workflow.");const c=useCompanyStore(),s=useAsyncData(()=>operationsRepository.purchaseOrders(c.activeCompanyId),{watch:[()=>c.activeCompanyId]}),q=ref(""),status=ref("all"),open=ref(false),supplier=ref(""),description=ref(""),router=useRouter();const rows=computed(()=>(s.data.value??[]).filter(x=>(status.value==='all'||x.status===status.value)&&`${x.number} ${x.supplier}`.toLowerCase().includes(q.value.toLowerCase()))),total=computed(()=>rows.value.reduce((a,x)=>a+x.total,0));const columns:Column[]=[{key:"number",header:"PO number"},{key:"supplier",header:"Supplier"},{key:"date",header:"Order date"},{key:"expected",header:"Expected"},{key:"owner",header:"Owner"},{key:"total",header:"Total",align:"right",class:"num"},{key:"received",header:"Received"},{key:"status",header:"Status"},{key:"actions",header:""}];function create(){open.value=false;showToast('Purchase order prepared','The preview order is ready for backend validation.','info')}</script><template><AppShell><PageHeader title="Purchase Orders" description="Controlled purchasing from request through receipt and supplier bill"><template #actions><ZButton @click="open=true"><Plus class="size-4"/>New purchase order</ZButton></template></PageHeader><div class="mb-4 grid gap-3 sm:grid-cols-3"><StatCard label="Open commitments" :value="formatMoney(total)" tone="brand"/><StatCard label="Awaiting approval" :value="String(rows.filter(x=>x.status==='pending').length)" tone="warning"/><StatCard label="Received" :value="String(rows.filter(x=>x.status==='received').length)" tone="success"/></div><Panel><Toolbar><SearchInput v-model="q" placeholder="Search PO or supplier"/><select v-model="status" class="field w-44"><option value="all">All statuses</option><option value="pending">Pending</option><option value="partially_received">Partially received</option><option value="received">Received</option></select></Toolbar><DataTable :columns="columns" :rows="rows" :min-width="1100"><template #number="{row}:{row:PurchaseOrder}"><button class="num font-medium text-content-brand hover:underline" @click="router.push(`/purchases/${row.id}`)">{{row.number}}</button></template><template #supplier="{row}">{{row.supplier}}</template><template #date="{row}">{{row.date}}</template><template #expected="{row}">{{row.expected_date}}</template><template #owner="{row}">{{row.owner}}</template><template #total="{row}">{{formatMoney(row.total)}}</template><template #received="{row}"><div class="w-28"><div class="h-1.5 rounded-full bg-surface-sunken"><div class="h-full rounded-full bg-primary" :style="{width:`${row.received}%`}"></div></div><span class="num text-2xs text-content-muted">{{row.received}}%</span></div></template><template #status="{row}"><StatusBadge :status="row.status"/></template><template #actions="{row}"><ZButton variant="ghost" @click="router.push(`/purchases/${row.id}`)">Review</ZButton></template></DataTable></Panel><SidePanel :open="open" title="New purchase order" description="Draft values remain editable until approval." width="lg" @close="open=false"><form class="grid gap-4 sm:grid-cols-2" @submit.prevent="create"><Field v-model="supplier" label="Supplier" required/><Field v-model="description" label="Description" required/><Field model-value="1" label="Quantity" type="number"/><Field model-value="0.00" label="Unit cost"/><label class="block sm:col-span-2"><span class="label-caps">Delivery notes</span><textarea class="field mt-1.5 min-h-24 w-full"></textarea></label><ZButton type="submit">Save draft</ZButton></form></SidePanel></AppShell></template>